#include <bits/stdc++.h>
using namespace std;

const string YES = "YES";
const string NO = "NO";

void solve(long long A, long long V, long long B, long long W, long long T)
{
    if (V <= W || abs(B - A) > (V - W) * T)
        cout << NO << endl;
    else
        cout << YES << endl;
}

