int main()
{
    long long A;
    scanf("%lld", &A);
    long long V;
    scanf("%lld", &V);
    long long B;
    scanf("%lld", &B);
    long long W;
    scanf("%lld", &W);
    long long T;
    scanf("%lld", &T);
    solve(A, V, B, W, T);
    return 0;
}
